"""Write evaluation/results/MODEL_RESULTS.md from model_metrics.json + blend_sweep.csv.
Run after `python training/train.py` and `python evaluation/blend_sweep.py`."""
import json
from pathlib import Path

import pandas as pd

R = Path(__file__).resolve().parent / "results"
m = json.loads((R / "model_metrics.json").read_text())
sw = pd.read_csv(R / "blend_sweep.csv")
p = lambda v: f"{v * 100:.1f}%"
d, h, c = m["data"], m["held_out_real"], m["same_sample_comparison"]

lines = [
    "# Trained model results",
    "",
    "Generated by `training/train.py`, `evaluation/blend_sweep.py` and `evaluation/model_report.py`.",
    "",
    "## Data",
    f"- **Real labelled postings:** {d['real_postings']:,} from `lukebarousse/data_jobs` (Apache-2.0, Google job postings 2023), "
    f"{d['unique_real_rows']:,} unique (skill set, career) rows. Careers with a real title label: {', '.join(d['real_classes'])}.",
    f"- **Weak labels:** {d['weak_postings']:,} 'Software Engineer' postings labelled python_developer / web_developer from their skills "
    "(not a title, so never counted in accuracy) plus "
    f"{d['synthetic_samples']:,} synthetic profiles from the knowledge base.",
    "- Train/validation/test are split by skill-set hash, so the same skill set never appears on both sides.",
    "",
    "## Held-out accuracy on real postings (5 real careers)",
    "| | Top-1 | Top-3 |",
    "|---|---|---|",
    f"| Always guess the biggest class | {p(h['majority_class_top1'])} | - |",
    f"| Rule-based recommender (same postings) | {p(c['rule_based']['top1'])} | {p(c['rule_based']['top3'])} |",
    f"| Logistic regression alone (same postings) | {p(c['model']['top1'])} | {p(c['model']['top3'])} |",
    f"| Logistic regression, full test fold | {p(h['model']['top1'])} | {p(h['model']['top3'])} |",
    "",
    f"Macro-F1 {h['model']['macro_f1']:.2f}. Per-career recall: " + ", ".join(f"{k} {p(v)}" for k, v in h["per_class_recall"].items()) + ".",
    "",
    "Job-title labels are noisy: a 'Data Analyst' and a 'Data Scientist' posting can list identical skills, so top-1 has a low ceiling "
    "and top-3 is the fairer headline.",
    "",
    "## Blending rules and model (`ML_WEIGHT`)",
    "`final = (1 - w) * rule_score + w * model_probability`. Fold 8 tunes w, fold 9 reports it; the personas are a student-style check.",
    "",
    "| w | real tune top-1 | real report top-1 | real report top-3 | core personas top-1 | hard strict | hard lenient |",
    "|---|---|---|---|---|---|---|",
] + [
    f"| {r.ml_weight:.1f} | {p(r.real_tune_top1)} | {p(r.real_report_top1)} | {p(r.real_report_top3)} | {p(r.core_top1)} | {p(r.hard_strict)} | {p(r.hard_lenient)} |"
    for r in sw.itertuples()
] + [
    "",
    "Chosen: **w = 0.5**. w = 0 is the old rule-only system, w = 1 is the model alone.",
    "",
    "## Limitations",
    "- Postings are US job ads, not student profiles: skills are what employers ask for, not what a student has.",
    "- Python Developer and Web Developer have no real title labels, so their accuracy is only checked on the hand-written personas.",
    "- Interests are not in the posting data; they enter only through the rule-based part.",
    "- The 52 personas are small and were written by the project team.",
]
(R / "MODEL_RESULTS.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
print("wrote", R / "MODEL_RESULTS.md")
